<script setup lang="ts">
const api = useApi(), data = ref<any>(null), error = ref(''), busy = ref(false)
const money = (minor: number) => new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(minor / 100)
async function load() { try { error.value = ''; data.value = await api('/api/wishlist-alerts') } catch (e) { error.value = errorMessage(e) } }
async function seen(id: string) { busy.value = true; try { await api('/api/wishlist-alerts/' + id + '/seen', { method: 'POST', body: {} }); await load() } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
onMounted(load)
</script>
<template><header class="page-heading"><div><h1>Wishlist alerts</h1><p class="muted">{{ data?.unread || 0 }} unread matches</p></div><div class="button-row"><NuxtLink to="/cards?ownership=wishlist" class="button secondary">My wishlist</NuxtLink><button class="button secondary" :disabled="busy" @click="load">Refresh</button></div></header><p v-if="error" class="alert error">{{ error }}</p><template v-if="data"><section class="panel alert-section"><h2>Latest matches</h2><p class="small muted">Checked by the catalogue worker, usually within a few minutes. Matches record the price at that time. Member listings can change or sell out.</p><p v-if="!data.events.length" class="muted">No matches yet. Open a wishlisted card to set a target.</p><article v-for="event in data.events" :key="event.id" class="alert-match"><div><span v-if="!event.seen_at" class="badge green">New</span><NuxtLink :to="'/cards?card=' + encodeURIComponent(event.card_id)"><strong>{{ event.name }} · {{ event.label }}</strong></NuxtLink><p>{{ event.kind === 'market' ? 'Market price' : 'Member listing total' }} {{ money(event.amount_aud_minor) }} · target {{ money(event.target_aud_minor) }}</p><small>{{ new Date(event.created_at).toLocaleString() }}</small><p v-if="event.kind === 'listing'"><NuxtLink v-if="event.listing_id && event.listing_active" :to="'/marketplace/' + event.listing_id">View listing</NuxtLink><span v-else class="muted">Listing is no longer active.</span></p></div><button v-if="!event.seen_at" class="text-button" :disabled="busy" @click="seen(event.id)">Mark read</button></article><p v-if="data.events.length === 100" class="data-note">Showing the latest 100 matches.</p></section><section class="panel alert-section"><h2>Saved alerts</h2><p v-if="!data.rules.length" class="muted">No alerts configured.</p><article v-for="rule in data.rules" :key="rule.id" class="alert-match"><div><NuxtLink :to="'/cards?card=' + encodeURIComponent(rule.card_id)"><strong>{{ rule.name }} · {{ rule.label }}</strong></NuxtLink><p>{{ money(rule.target_aud_minor) }} · {{ rule.enabled && rule.wishlisted && rule.catalogue_available ? 'Enabled' : 'Paused' }} · {{ [rule.watch_market ? 'Market prices' : '', rule.watch_listings ? 'Member listings' : ''].filter(Boolean).join(' / ') }}</p><small>{{ rule.set_name }} · {{ rule.language.toUpperCase() }} · {{ rule.conditions.join(', ') }}</small></div></article><p class="data-note">Manage an alert from its card details. Checks pause when the printing leaves your wishlist, becomes unavailable or your membership/game access changes.</p></section></template></template>
<style scoped>.alert-section{padding:20px;margin-bottom:20px}.alert-section h2{font-size:19px}.alert-match{display:flex;gap:16px;justify-content:space-between;border-top:1px solid var(--line);padding:16px 0;font-size:13px}.alert-match>div{min-width:0;overflow-wrap:anywhere}.alert-match p{margin:8px 0}.alert-match small{color:var(--muted)}.alert-match button{flex-shrink:0;align-self:start}</style>
